-- Portfolio : les 16 campagnes du document « Campagnes LYD — Textes Dev », ajoutées EN BROUILLON à la suite des campagnes existantes.
-- Elles n'apparaissent pas sur le site tant qu'elles ne sont pas publiées : relire chaque texte, ajouter une vraie photo,
-- puis passer le statut à « Publiée » dans l'admin (Campagnes). Les campagnes existantes ne sont pas modifiées.
-- À exécuter une fois dans Supabase > SQL Editor. Le relancer n'ajoute pas de doublon (même identifiant).
begin;

update public.site_content s set value = s.value || coalesce((
  select jsonb_agg(n.x order by n.i)
  from jsonb_array_elements('[{"id":"wakabi","t":"Wakabi","client":"Wakabi","sec":"Boisson locale — Lomé, Togo","year":"","cat":"Campagne 360°","f":"Campagne 360°","a":"La saveur locale amplifiée à grande échelle.","d":"Campagne 360° pour Wakabi, marque togolaise de référence dans le secteur des boissons locales. LYD a orchestré l''ensemble du dispositif de communication : stratégie de marque, production de contenus digitaux, activation terrain et couverture médias pour ancrer Wakabi dans le quotidien des Togolais et renforcer sa présence sur le marché.","tags":["Stratégie","Digital","Print","Activation terrain","Relations médias"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"ecobank","t":"Ecobank","client":"Ecobank","sec":"Banque panafricaine — Lomé, Togo","year":"","cat":"Campagne 360°","f":"Campagne 360°","a":"Une institution africaine, une présence de tous les jours.","d":"Dispositif de communication intégré pour Ecobank Togo, institution financière leader en Afrique subsaharienne. Publicité digitale, production de contenus et couverture événementielle pour renforcer la relation de confiance avec les clients togolais et soutenir les temps forts de la marque au Togo.","tags":["Stratégie","Digital","Événementiel","Production contenus","Publicité"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"homme-allie","t":"Homme Allié","client":"Homme Allié","sec":"Campagne engagement genre — Société civile, Togo","year":"","cat":"Campagne Production","f":"Campagne Production","a":"Des hommes qui prennent position pour l''égalité.","d":"Production audiovisuelle pour la campagne « Homme Allié », portée par des organisations engagées pour l''égalité de genre au Togo. Films courts de sensibilisation, spots de mobilisation et contenus de campagne déployés sur les plateformes digitales et en projections communautaires pour toucher le cœur et changer les comportements.","tags":["Production vidéo","Écriture de scénario","Direction artistique","Post-production","Distribution digitale"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"abiscream","t":"AbisCream","client":"AbisCream","sec":"Cosmétiques naturels — Lomé, Togo","year":"","cat":"Campagne Digitale","f":"Campagne Digitale","a":"La beauté togolaise, racontée avec soin.","d":"Stratégie et animation des réseaux sociaux pour AbisCream, marque togolaise de soins et de cosmétiques naturels. Création de contenus produits, campagnes de visibilité sur Meta et construction d''une communauté engagée autour des valeurs de beauté naturelle portées par la marque.","tags":["Social Media","Création de contenus","Meta Ads","Community Management"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"conii-gangster","t":"Conii Gangster","client":"Conii Gangster","sec":"Artiste rap — Lomé, Togo","year":"","cat":"Campagne Digitale","f":"Campagne Digitale","a":"La rue togolaise a sa voix digitale.","d":"Stratégie digitale de lancement et de promotion pour l''artiste togolais Conii Gangster. Création d''un univers visuel cohérent, campagnes de promotion autour des sorties musicales et activation de la communauté de fans sur les plateformes Meta pour accroître la notoriété et les streams.","tags":["Social Media","Promotion musicale","Publicité digitale","Création de contenus"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"beatpopovelo","t":"Beatpopovelo","client":"Beatpopovelo","sec":"Beatmaker & producteur musical — Lomé, Togo","year":"","cat":"Campagne Digitale","f":"Campagne Digitale","a":"La musique togolaise mise en scène.","d":"Accompagnement digital pour le beatmaker togolais Beatpopovelo. Mise en place d''une présence affirmée sur les réseaux sociaux, création de contenus valorisant l''univers créatif du producteur et campagnes ciblant les amateurs de musique urbaine africaine.","tags":["Social Media","Direction artistique digitale","Création de contenus","Community Management"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"gnadoe-media","t":"Gnadoe Media","client":"Gnadoe Media","sec":"Média digital — Togo","year":"","cat":"Campagne Digitale","f":"Campagne Digitale","a":"L''information togolaise portée plus loin.","d":"Conseil stratégique et renforcement de la présence digitale de Gnadoe Media, référence de l''actualité en ligne au Togo. Optimisation de l''engagement organique, campagnes de croissance d''audience et co-production de formats éditoriaux pour maximiser la portée et la fidélité des lecteurs.","tags":["Stratégie digitale","Social Media","Publicité","Co-production éditoriale"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"battle-arena","t":"Battle Arena","client":"Battle Arena","sec":"Tournoi de danse — LYD Original — Lomé","year":"","cat":"Event","f":"Event","a":"Lomé danse. L''arène décide.","d":"Concept, production et communication de Battle Arena, le grand tournoi de danse urbaine co-créé et organisé par LYD. Trois éditions qui ont réuni danseurs, chorégraphes, jurys professionnels et un large public à Lomé, avec une couverture TV nationale (VOX Africa, RTT, AFN), radio et digitale. Battle Arena est devenu un rendez-vous culturel incontournable de la scène togolaise.","tags":["Conception événementielle","Production","Communication 360°","Couverture médias","Vidéo","Livestream"],"res":[],"img":"","status":"brouillon","orig":true},{"id":"electriciens-sans-frontieres","t":"Électriciens sans frontières","client":"Électriciens sans frontières","sec":"ONG internationale — Atelier SISAM2, Lomé","year":"","cat":"Event","f":"Event","a":"Vingt ans de terrain togolais. Une restitution à la hauteur.","d":"Organisation et production complète de l''atelier de restitution final du projet SISAM2 d''Électriciens sans frontières à Lomé, réunissant 40 à 50 décideurs, ONG et partenaires togolais. Coordination logistique clé en main : lieu, technique (son, projection, visioconférence), accueil et protocole, restauration, kakémonos, relations médias, couverture photographique et accompagnement logistique des délégués venus de l''intérieur du pays.","tags":["Logistique événementielle","Technique AV","Relations médias","Photographie","Print","Protocole"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"ids-magazine","t":"IDS Magazine","client":"IDS Magazine","sec":"Magazine annuel d''entreprise — IDS Technologie","year":"","cat":"Projet Développé","f":"Projet Développé","a":"Les avancées d''une structure, racontées avec clarté.","d":"Conception et production du magazine annuel d''IDS Technologie, distribué aux clients, partenaires et acteurs clés de l''écosystème. Chaque édition documente les projets, innovations et expertises de la structure, en faisant un outil éditorial qui renforce son positionnement institutionnel et entretient ses relations stratégiques au fil de l''année.","tags":["Conception éditoriale","Rédaction","Direction artistique","Impression","Distribution"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"spiro","t":"Spiro","client":"Spiro","sec":"Mobilité électrique — Togo & Afrique","year":"","cat":"Campagne Ads","f":"Campagne Ads","a":"La mobilité électrique africaine, boostée au digital.","d":"Campagne de publicité digitale pour Spiro, pionnier des motos électriques en Afrique subsaharienne. Achat média sur Meta et Google Ads pour accroître la notoriété de la marque au Togo, générer des contacts qualifiés et accompagner le déploiement commercial sur un marché en forte croissance.","tags":["Meta Ads","Google Ads","Media Buying","Stratégie performance","Reporting"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"union-europeenne-agir-ensemble","t":"Union européenne — Agir Ensemble Tour","client":"Union européenne — Agir Ensemble Tour","sec":"Délégation de l''Union européenne au Togo","year":"","cat":"Campagne Ads","f":"Campagne Ads","a":"Une institution mondiale, amplifiée au niveau local.","d":"Campagne d''achat média sur les réseaux sociaux pour les émissions itinérantes « Agir Ensemble Tour » de la Délégation de l''Union européenne au Togo, des rendez-vous qui créent le dialogue autour de l''énergie, de l''environnement et de l''entrepreneuriat à Lomé et en régions. Déploiement sur Meta (Facebook, Instagram, Reels) et Google (YouTube, Display), avec un pilotage des performances en temps réel via des tableaux de bord Looker Studio partagés avec l''équipe de la Délégation.","tags":["Meta Ads","Google Ads","Media Buying","Looker Studio","Performance marketing"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"woodin","t":"Woodin","client":"Woodin","sec":"Textile wax — Afrique de l''Ouest","year":"","cat":"Magazine & Print","f":"Magazine & Print","a":"Le wax africain, magnifié par l''image.","d":"Production de contenus print et éditoriaux pour Woodin, marque iconique du tissu wax en Afrique de l''Ouest. Direction artistique, shooting produit et création de supports de communication qui capturent l''identité de la marque entre héritage africain et modernité contemporaine.","tags":["Direction artistique","Shooting photo","Création print","Maquettage","Infographie"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"daba","t":"Daba","client":"Daba","sec":"Élevage de poulets bio — Lomé, Togo","year":"","cat":"Documentaire","f":"Documentaire","a":"Du champ à l''assiette, par des Togolais, pour les Togolais.","d":"Réalisation du documentaire institutionnel de Daba, entreprise togolaise d''élevage de poulets bio. Un film qui retrace avec authenticité chaque étape du processus de production, de la ferme à la distribution, valorise le savoir-faire et l''engagement local de l''équipe, et ancre Daba comme référence du poulet naturel au Togo.","tags":["Production documentaire","Réalisation","Direction artistique","Post-production","Distribution digitale"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"bonici-africa","t":"Bonici Africa","client":"Bonici Africa","sec":"Restaurant africain — Lomé, Togo","year":"","cat":"Photo Culinaire","f":"Photo Culinaire","a":"La gastronomie africaine sublimée en images.","d":"Shooting photo culinaire pour Bonici Africa, restaurant qui met à l''honneur les saveurs du continent. Des visuels vibrants et appétissants pensés pour les réseaux sociaux, les menus et les supports print : chaque plat capturé avec le soin d''une véritable direction artistique gastronomique.","tags":["Photographie culinaire","Direction artistique","Retouche photo","Contenus réseaux sociaux","Print"],"res":[],"img":"","status":"brouillon","orig":false},{"id":"doms","t":"Dom''s","client":"Dom''s","sec":"Restaurant spécialisé fried rice — Lomé, Togo","year":"","cat":"Photo Culinaire","f":"Photo Culinaire","a":"Le fried rice de Lomé, dans toute sa splendeur.","d":"Shooting photo culinaire pour Dom''s, restaurant spécialisé dans le fried rice. Des visuels soignés qui donnent faim au premier regard : plats sublimés, ambiance chaleureuse, contenus directement utilisables sur Instagram et Facebook pour transformer chaque post en envie de commander.","tags":["Photographie culinaire","Direction artistique","Retouche photo","Contenus réseaux sociaux"],"res":[],"img":"","status":"brouillon","orig":false}]'::jsonb) with ordinality as n(x, i)
  where not exists (select 1 from jsonb_array_elements(s.value) e where e ->> 'id' = n.x ->> 'id')
), '[]'::jsonb), updated_at = now()
where s.key = 'campaigns';

select x ->> 'id' as id, x ->> 't' as campagne, x ->> 'f' as categorie, x ->> 'status' as statut
from public.site_content, jsonb_array_elements(value) x where key = 'campaigns';

commit;
